head.b:skin:
:root{--ink:#1f2933;--mute:#66707a;--line:#d9dde2;--bg:#ffffff;--soft:#f4f6f8;--acc:#2f6fb3;--good:#2e8b57;--bad:#c0392b}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font-family:system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;line-height:1.4}
button{font:inherit;cursor:pointer}
.wrap{max-width:960px;margin:0 auto;padding:0 16px 40px}
header{border-bottom:1px solid var(--line);background:#fff;position:sticky;top:0;z-index:5}
.hbar{max-width:960px;margin:0 auto;padding:10px 16px;display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.hbar h1{font-size:18px;margin:0;flex:1;min-width:160px}
.tok{background:var(--soft);border:1px solid var(--line);border-radius:999px;padding:6px 14px;font-weight:700}
.who{color:var(--mute);font-size:14px}
.save{font-size:12px;color:var(--mute)}
.bookln{margin-left:auto;font-size:14px;font-weight:700;color:#f2a24f}
.save.err{color:var(--bad)}
nav{max-width:960px;margin:0 auto;padding:0 16px 10px;display:flex;gap:8px}
nav button{flex:1;padding:10px;border:1px solid var(--line);background:#fff;border-radius:8px;font-weight:600;color:var(--ink)}
nav button.on{background:var(--acc);color:#fff;border-color:var(--acc)}
.btn{background:var(--acc);color:#fff;border:0;border-radius:8px;padding:11px 18px;font-weight:600}
.btn.alt{background:#fff;color:var(--ink);border:1px solid var(--line)}
.btn:disabled{background:#c9ced4;color:#fff;cursor:not-allowed}
.panel{border:1px solid var(--line);border-radius:12px;padding:18px;margin-top:16px;background:#fff}
h2{margin:0 0 8px;font-size:20px}
.mute{color:var(--mute)}
input[type=text]{font:inherit;padding:11px 12px;border:1px solid #b9c0c8;border-radius:8px;width:100%;margin:4px 0 12px}
label{font-weight:600;font-size:14px}
.q{font-size:20px;font-weight:600;margin:6px 0 14px}
.choice{display:block;width:100%;text-align:left;padding:13px 14px;margin:8px 0;border:1px solid #b9c0c8;border-radius:8px;background:#fff;color:var(--ink)}
.choice:hover:not(:disabled){background:var(--soft)}
.choice.right{background:#e6f4ec;border-color:var(--good);color:#14502f;font-weight:600}
.choice.wrong{background:#fbe9e7;border-color:var(--bad);color:#8a2118}
.fb{margin:10px 0;font-weight:600}
.fb.good{color:var(--good)}.fb.bad{color:var(--bad)}
.prog{height:8px;background:var(--soft);border-radius:99px;overflow:hidden;margin-bottom:10px}
.prog i{display:block;height:100%;background:var(--acc)}
.packs{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin-top:12px}
.pack{border:1px solid var(--line);border-radius:12px;padding:16px;text-align:center}
.pack h3{margin:0 0 4px}
.cost{font-size:26px;font-weight:800;margin:4px 0}
.odds{font-size:14px;color:var(--mute);margin:6px 0 12px}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:14px;margin-top:14px}
.slot{text-align:center}
.frame{padding:4px;border-radius:12px;background:#8d949b;position:relative}
.frame.rare{background:linear-gradient(135deg,#f5f7fa,#9aa5b1 45%,#e8edf2 60%,#8a96a3);box-shadow:0 0 0 1px #aab4bf,0 2px 8px rgba(80,95,110,.35)}
.frame.legendary{background:linear-gradient(135deg,#fff3b0,#d9a520 45%,#fff0a0 60%,#c8921a);box-shadow:0 0 0 1px #d4a82e,0 3px 12px rgba(200,150,20,.5)}
.frame img{display:block;width:100%;border-radius:8px;aspect-ratio:3/4;object-fit:cover;background:#fff}
.frame.empty img,.empty .blank{opacity:1}
.blank{aspect-ratio:3/4;border-radius:8px;background:var(--soft);display:flex;align-items:center;justify-content:center;color:#9aa3ad;font-size:34px;font-weight:700}
.frame.empty{background:var(--line);box-shadow:none}
.cn{font-weight:700;font-size:14px;margin-top:6px}
.rar{font-size:12px;text-transform:uppercase;letter-spacing:.05em;color:var(--mute)}
.rar.rare{color:#5b6b7b}.rar.legendary{color:#a67800}
.frame .inner{background:#fbf6e9;border-radius:9px;padding:4px}
.frame .nm{background:#fff;border:1px solid #3a3f47;border-radius:6px;padding:3px 5px;font-size:11px;font-weight:700;line-height:1.15;min-height:2.3em;display:flex;align-items:center;justify-content:center;text-align:center;color:#1f2933;margin-bottom:4px}
.frame .inner img{border:1.5px solid #3a3f47;border-radius:5px}
.frame .st{display:flex;align-items:center;justify-content:space-between;gap:3px;margin-top:5px}
.frame .pill{display:flex;align-items:center;gap:3px;background:#fff;border:1.5px solid #3a3f47;border-radius:99px;padding:1px 7px 1px 4px;font-weight:800;font-size:16px;line-height:1.2;color:#1f2933}
.frame .pill.r{padding:1px 4px 1px 7px}
.frame .pill svg{width:14px;height:14px}
.frame .up{text-align:center;line-height:1.05}.frame .up i{display:block;font-style:normal;font-size:7px;letter-spacing:.08em;color:#66707a;font-weight:700}.frame .up b{font-size:14px;color:#2e8b57}
.cnt{position:absolute;top:-8px;right:-8px;background:var(--ink);color:#fff;border-radius:99px;min-width:26px;height:26px;padding:0 7px;display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:700}
.sell{margin-top:6px;font-size:13px;padding:6px 10px}
.modal{position:fixed;inset:0;background:rgba(255,255,255,.94);display:flex;align-items:center;justify-content:center;z-index:20;padding:16px}
.modal .box{max-width:340px;width:100%;text-align:center}
.modal .frame{animation:pop .45s ease-out}
@keyframes pop{from{transform:scale(.6) rotate(-4deg);opacity:0}to{transform:none;opacity:1}}
.badge{display:inline-block;padding:3px 10px;border-radius:99px;font-size:13px;font-weight:700;margin:8px 0}
.badge.new{background:#e6f4ec;color:#14502f}.badge.dup{background:var(--soft);color:var(--mute)}
.stats{display:flex;gap:18px;flex-wrap:wrap;margin:8px 0}
.stats div b{display:block;font-size:22px}
.hide{display:none}
nav button{padding:10px 4px}
@media(max-width:560px){nav{flex-wrap:wrap}nav button{flex:1 1 44%;font-size:14px}}
.brow{border:1px solid var(--line);border-radius:12px;padding:10px 12px;margin-bottom:10px;background:#fff}
.brow.me{border-color:var(--acc);background:#f0f6fc}
.bhead{display:flex;align-items:center;gap:10px}
.rk{width:30px;height:30px;border-radius:50%;background:#eef0f3;color:#66707a;font-weight:800;display:flex;align-items:center;justify-content:center;flex:none}
.rk.g1{background:#d9a520;color:#fff}.rk.g2{background:#9aa5b1;color:#fff}.rk.g3{background:#b87333;color:#fff}
.bn{font-weight:700;font-size:17px;flex:1;min-width:0;overflow-wrap:anywhere}
.bp{text-align:right;white-space:nowrap}.bp b{font-size:20px}.bp span{color:var(--mute);font-size:13px}
.mini{display:flex;flex-wrap:wrap;gap:4px;margin-top:8px}
.mc{padding:2px;border-radius:5px;background:#8d949b;border:0;cursor:pointer}
.mc.rare{background:linear-gradient(135deg,#f5f7fa,#9aa5b1 50%,#e8edf2)}
.mc.legendary{background:linear-gradient(135deg,#fff3b0,#d9a520 50%,#fff0a0)}
.mc{width:52px}.mc img{display:block;width:100%;height:auto;aspect-ratio:3/4;border-radius:2px;object-fit:cover}
.mcap{font-size:13px;color:var(--mute);margin-top:6px;min-height:1em}
.note{font-size:13px;color:var(--mute);margin-top:10px}

/* ===== HALLOWEEN THEME (look only) ===== */
:root{--ink:#ece6f5;--mute:#9d92b3;--line:#2f2640;--bg:#0c0911;--soft:#1a1326;--acc:#e07a1f;--good:#62c98f;--bad:#f27d70;--glass:rgba(24,17,36,.82);--edge:rgba(255,255,255,.07)}
body{background:radial-gradient(900px 420px at 50% -120px,rgba(110,60,150,.28) 0%,rgba(12,9,17,0) 70%) no-repeat,radial-gradient(700px 360px at 100% 100%,rgba(224,122,31,.07) 0%,rgba(12,9,17,0) 70%) no-repeat,#0c0911;background-attachment:fixed;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif}
body::before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.05;z-index:0;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='160' height='160' filter='url(%23n)'/></svg>")}
.wrap,header,nav{position:relative;z-index:1}
h1,h2,h3{font-family:"Palatino Linotype",Palatino,"Book Antiqua",Georgia,serif;letter-spacing:.04em}
header{background:rgba(14,10,21,.92);border-bottom:1px solid #3a2c52;box-shadow:0 1px 0 rgba(224,122,31,.35),0 8px 24px rgba(0,0,0,.45)}
.hbar h1{color:#f2a24f;font-size:16px;text-transform:uppercase;letter-spacing:.08em;text-shadow:0 0 16px rgba(224,122,31,.35)}
.tok{background:#1d1530;border-color:#3d2f57;color:#f5c27a}
.who{color:#9d92b3}
nav button{background:var(--glass);color:#cfc5e0;border-color:var(--line);transition:background .18s,border-color .18s,color .18s,box-shadow .18s}
nav button:hover{border-color:#5a4585;color:#fff}
nav button.on{background:linear-gradient(180deg,#e98a30,#c8661a);color:#1a0f08;border-color:#f2a24f;box-shadow:0 0 14px rgba(224,122,31,.35)}
.btn{background:linear-gradient(180deg,#e98a30,#c8661a);color:#1a0f08;transition:box-shadow .18s,transform .18s,filter .18s}
.btn:hover:not(:disabled){box-shadow:0 0 16px rgba(224,122,31,.55);transform:translateY(-1px)}
.btn.alt{background:#1d1530;color:#ece6f5;border-color:#3d2f57}
.btn.alt:hover:not(:disabled){box-shadow:0 0 12px rgba(160,120,220,.3)}
.btn:disabled{background:#2a2238;color:#6f6585}
.panel,.pack,.brow{background:var(--glass);border-color:var(--line);box-shadow:inset 0 1px 0 var(--edge),0 10px 28px rgba(0,0,0,.35)}
.pack{background:rgba(32,23,48,.85);transition:transform .2s,box-shadow .2s,border-color .2s}
.pack:hover{transform:translateY(-3px);border-color:#5a4585;box-shadow:inset 0 1px 0 var(--edge),0 14px 30px rgba(0,0,0,.5),0 0 18px rgba(224,122,31,.18)}
.brow.me{background:rgba(52,32,14,.75);border-color:#c8661a}
input[type=text]{background:#0f0b17;color:#ece6f5;border-color:#3d2f57}
input[type=text]:focus{outline:none;border-color:#e07a1f;box-shadow:0 0 0 3px rgba(224,122,31,.2)}
.choice{background:rgba(32,23,48,.85);color:#ece6f5;border-color:#3d2f57;transition:background .15s,border-color .15s}
.choice:hover:not(:disabled){background:#2c2142;border-color:#6a5496}
.choice.right{background:#12301f;border-color:#62c98f;color:#c8f5d8}
.choice.wrong{background:#3a1814;border-color:#f27d70;color:#ffd0ca}
.prog{background:#251c35}.prog i{background:linear-gradient(90deg,#c8661a,#f2a24f)}
.rk{background:#2a2038;color:#c9bde3}
.badge.new{background:#12301f;color:#9ff0bf}.badge.dup{background:#251c35;color:#c9bde3}
.rar.rare{color:#c5d0dc}.rar.legendary{color:#f0b942}
.cnt{background:#e07a1f;color:#1a0f08}
.frame.empty{background:#2a2038}.blank{background:#1a1326;color:#4f4468}
.frame{box-shadow:0 3px 12px rgba(0,0,0,.6);transition:transform .2s,box-shadow .2s}
.slot:hover .frame:not(.empty){transform:translateY(-4px);box-shadow:0 10px 22px rgba(0,0,0,.7)}
.slot:hover .frame.legendary{box-shadow:0 10px 24px rgba(0,0,0,.7),0 0 22px rgba(240,185,66,.4)}
.note,.mute{color:#9d92b3}
.modal{background:rgba(7,4,12,.96)}
/* pack opening */
.modal .frame{animation:none}
.stage{position:relative;width:min(300px,78vw);margin:0 auto 6px;perspective:900px}
.stage .fx{position:absolute;inset:-60px;pointer-events:none;z-index:3}
.flip{position:relative;width:100%;aspect-ratio:3/4.55;transform-style:preserve-3d;animation:shake 1.5s ease-in 0s 1 both,turn .8s cubic-bezier(.3,.7,.2,1) 1.7s 1 both}
.flip>div{position:absolute;inset:0;backface-visibility:hidden;-webkit-backface-visibility:hidden}
.flip .front{transform:rotateY(180deg)}
.flip .front .frame{height:100%}
.back{border-radius:14px;padding:7px;background:linear-gradient(135deg,#ff9a3c,#7a3aa8 50%,#ff9a3c);box-shadow:0 0 28px rgba(232,115,26,.55)}
.back .bi{height:100%;border-radius:9px;background:radial-gradient(circle at 50% 40%,#3b2162,#150e22 75%);border:2px solid #e8731a;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;color:#ffb869;font-weight:700;letter-spacing:.2em;font-size:15px}
.back svg{width:96px;height:96px;filter:drop-shadow(0 0 10px rgba(255,140,40,.7))}
@keyframes shake{0%{transform:translateY(0) rotate(0)}10%{transform:translateX(-4px) rotate(-2deg)}20%{transform:translateX(5px) rotate(2deg)}30%{transform:translateX(-6px) rotate(-3deg)}40%{transform:translateX(6px) rotate(3deg)}50%{transform:translateX(-7px) rotate(-3deg) scale(1.03)}60%{transform:translateX(7px) rotate(3deg) scale(1.05)}70%{transform:translateX(-8px) rotate(-4deg) scale(1.07)}80%{transform:translateX(8px) rotate(4deg) scale(1.09)}100%{transform:scale(1.12)}}
@keyframes turn{from{transform:scale(1.12) rotateY(0)}to{transform:scale(1) rotateY(180deg)}}
.flash{position:absolute;inset:-80px;border-radius:50%;background:radial-gradient(circle,#fff 0%,rgba(255,200,120,.9) 25%,rgba(255,140,40,0) 65%);opacity:0;z-index:4;pointer-events:none;animation:flash .7s ease-out 1.55s 1 both}
.stage.rare .flash{background:radial-gradient(circle,#fff 0%,rgba(190,210,235,.95) 28%,rgba(150,170,200,0) 66%)}
.stage.legendary .flash{animation-duration:1s;background:radial-gradient(circle,#fff 0%,rgba(255,215,90,.98) 30%,rgba(255,170,30,0) 70%)}
@keyframes flash{0%{opacity:0;transform:scale(.3)}30%{opacity:1}100%{opacity:0;transform:scale(1.4)}}
.sp{position:absolute;left:50%;top:50%;width:7px;height:7px;border-radius:50%;background:#ffb869;opacity:0;animation:sp 1.1s ease-out 1.7s 1 both}
.stage.rare .sp{background:#dfe8f2;box-shadow:0 0 8px #fff}
.stage.legendary .sp{background:#ffd54a;box-shadow:0 0 10px #ffb300;width:9px;height:9px}
@keyframes sp{0%{opacity:0;transform:translate(0,0) scale(.4)}15%{opacity:1}100%{opacity:0;transform:translate(var(--x),var(--y)) scale(1)}}
.stage.legendary .front .frame{animation:glow 1.6s ease-in-out 2.5s infinite alternate}
.stage.rare .front .frame{animation:glowr 1.8s ease-in-out 2.5s infinite alternate}
@keyframes glow{from{box-shadow:0 0 12px rgba(255,200,60,.5)}to{box-shadow:0 0 34px rgba(255,200,60,.95)}}
@keyframes glowr{from{box-shadow:0 0 8px rgba(200,215,235,.4)}to{box-shadow:0 0 22px rgba(210,225,245,.85)}}
.reveal-info{opacity:0;animation:fadein .5s ease-out 2.6s 1 both}
@keyframes fadein{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}

/* pack pictures */
.pk{position:relative;width:min(210px,100%);margin:0 auto 10px;container-type:inline-size}
.pk img{display:block;width:100%;height:auto;filter:drop-shadow(0 6px 14px rgba(0,0,0,.6))}
.ptag{position:absolute;display:flex;align-items:center;justify-content:center;font-weight:800;letter-spacing:.12em;font-size:7cqw;white-space:nowrap;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;text-shadow:0 0 10px currentColor}
.pack:hover .pk img{filter:drop-shadow(0 8px 18px rgba(224,122,31,.45))}
/* pack opening (tear and reveal) */
.stage{aspect-ratio:3/4.55}
.cardwrap{position:absolute;inset:0;z-index:2;opacity:0;animation:emerge .95s cubic-bezier(.2,.9,.25,1.15) 1.75s 1 both}
.cardwrap .frame{height:100%}
@keyframes emerge{from{opacity:0;transform:translateY(18%) scale(.5) rotate(-5deg)}60%{opacity:1}to{opacity:1;transform:none}}
.pk2{position:absolute;left:11%;top:3%;width:78%;aspect-ratio:768/1376;z-index:3;animation:shake 1.5s ease-in 0s 1 both,pglow 1.5s ease-in 0s 1 both}
.pk2 img{position:absolute;inset:0;width:100%;height:100%;display:block}
.pk2 .pbody{clip-path:inset(11% 0 0 0);animation:pbody .6s ease-in 1.6s 1 both}
.pk2 .ptop{clip-path:inset(0 0 89% 0);transform-origin:20% 100%;animation:ptop .7s ease-in 1.6s 1 both}
@keyframes pbody{to{transform:translateY(40px) scale(.9);opacity:0}}
@keyframes ptop{to{transform:translate(70px,-150px) rotate(24deg);opacity:0}}
@keyframes pglow{from{filter:drop-shadow(0 0 4px rgba(224,122,31,.2))}to{filter:drop-shadow(0 0 26px rgba(255,170,60,.95))}}
.stage.rare .pk2{animation-name:shake,pglowr}.stage.legendary .pk2{animation-name:shake,pglowl}
@keyframes pglowr{from{filter:drop-shadow(0 0 4px rgba(200,215,235,.2))}to{filter:drop-shadow(0 0 26px rgba(215,230,250,.95))}}
@keyframes pglowl{from{filter:drop-shadow(0 0 4px rgba(255,200,60,.3))}to{filter:drop-shadow(0 0 32px rgba(255,210,70,1))}}
.stage.legendary .cardwrap .frame{animation:glow 1.6s ease-in-out 2.7s infinite alternate}
.stage.rare .cardwrap .frame{animation:glowr 1.8s ease-in-out 2.7s infinite alternate}
/* scoreboard small cards, new look */
.mi{display:block;background:#fbf6e9;border-radius:3px;padding:2px}
.ms{display:block;text-align:center;font:800 11px/1.3 system-ui,sans-serif;color:#1f2933;margin-top:1px}

/* ===== BATTLE ===== */
.rec{display:flex;gap:22px;flex-wrap:wrap;margin:8px 0}.rec div b{display:block;font-size:22px}
.rules{margin:8px 0 0;padding-left:20px}.rules li{margin:3px 0}
.dgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:14px;margin-top:14px}
.dpick{background:none;border:0;padding:0;text-align:center;color:inherit;position:relative;border-radius:14px}
.dpick .frame{transition:box-shadow .2s,transform .2s}
.dpick:hover:not(.off) .frame{transform:translateY(-3px)}
.dpick.sel .frame{box-shadow:0 0 0 3px #e07a1f,0 0 22px rgba(224,122,31,.6)}
.dpick.off{opacity:.3;cursor:not-allowed}
.dpick .tick{position:absolute;top:-8px;left:-8px;background:#e07a1f;color:#1a0f08;border-radius:99px;width:26px;height:26px;font-weight:800;display:none;align-items:center;justify-content:center;z-index:3}
.dpick.sel .tick{display:flex}
.btag{display:inline-block;padding:3px 12px;border-radius:99px;font-weight:800;font-size:12px;letter-spacing:.14em;text-transform:uppercase;background:#2a2038;color:#c9bde3}
.btag.boss{background:#5a1712;color:#ffb0a6;box-shadow:0 0 14px rgba(242,125,112,.45)}
.arena{padding:12px}
.abar{display:flex;align-items:center;gap:10px;justify-content:space-between;flex-wrap:wrap}
.brow3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;max-width:520px;margin:10px auto}
.bc{position:relative;transition:filter .3s,opacity .3s}
.bc .frame .pill,.dpick .frame .pill{font-size:clamp(10px,3vw,15px);padding:1px 4px 1px 3px;gap:2px}.bc .frame .pill.r,.dpick .frame .pill.r{padding:1px 3px 1px 4px}.bc .frame .pill svg,.dpick .frame .pill svg{width:clamp(9px,2.6vw,13px);height:clamp(9px,2.6vw,13px)}.bc .frame .up i,.dpick .frame .up i{font-size:6px;letter-spacing:0}.bc .frame .up b,.dpick .frame .up b{font-size:clamp(10px,3vw,13px)}
.bc .frame .nm{font-size:clamp(9px,2.6vw,11px)}
.bc.pickable{cursor:pointer}
.bc.pickable:hover .frame{transform:translateY(-4px)}
.bc.sel .frame{box-shadow:0 0 0 3px #e07a1f,0 0 24px rgba(224,122,31,.75)}
.bc.tgt{cursor:crosshair}
.bc.tgt .frame{box-shadow:0 0 0 3px #f27d70,0 0 22px rgba(242,125,112,.7);animation:tg 1s ease-in-out infinite alternate}
@keyframes tg{to{box-shadow:0 0 0 3px #f27d70,0 0 6px rgba(242,125,112,.3)}}
.bc.ko{filter:grayscale(1) brightness(.5);opacity:.6}
.kot{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font:800 30px Palatino,Georgia,serif;color:#fff;letter-spacing:.2em;text-shadow:0 0 10px #000;pointer-events:none}
.hp{height:7px;border-radius:99px;background:#251c35;margin-top:5px;overflow:hidden}.hp i{display:block;height:100%;transition:width .4s}
.hpt{font-size:12px;text-align:center;color:var(--mute);margin-top:2px}
.fl{position:absolute;left:50%;top:28%;transform:translateX(-50%);font:800 clamp(22px,7vw,34px) system-ui,sans-serif;pointer-events:none;z-index:40;text-shadow:0 0 8px #000,0 2px 0 #000;white-space:nowrap}
.fl.dmg{color:#ff6b5e}.fl.up{color:#7dffb0}
.fxo{position:absolute;inset:0;border-radius:14px;pointer-events:none;z-index:35}
.bmsg{text-align:center;min-height:2.6em;margin:6px 0;font-weight:600}
.pips{display:inline-flex;gap:5px;vertical-align:middle;margin-left:6px}.pips i{width:12px;height:12px;border-radius:50%;background:#e07a1f;box-shadow:0 0 8px rgba(224,122,31,.7)}.pips i.u{background:#2a2038;box-shadow:none}
.acts{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin:8px 0}
.qbox{max-width:560px;margin:8px auto 0;border-top:1px solid var(--line);padding-top:10px}
.nav5 nav button{font-size:14px}
.tabs2{display:flex;gap:8px;margin-bottom:10px}.tabs2 button{flex:1}
.tabs2 .btn.alt.on{background:linear-gradient(180deg,#e98a30,#c8661a);color:#1a0f08;border-color:#f2a24f}
/* ===== TITLE SCREEN + BACKGROUND ===== */
.bgimg{position:fixed;inset:0;z-index:0;background-color:#0c0911;background-size:cover;background-position:center;background-repeat:no-repeat;pointer-events:none}
#login.wrap{max-width:1200px;padding-top:16px}
.hero{position:relative}
.heroimg{display:block;width:100%;height:auto;border-radius:14px;box-shadow:0 10px 30px rgba(0,0,0,.6)}
.loginbox{max-width:460px;margin:16px auto 0}
@media(min-width:1024px){
 .loginbox{position:absolute;left:2.5%;bottom:3.5%;width:min(340px,32%);margin:0;padding:14px 16px;background:rgba(14,10,21,.84);border-color:#3a2c52;backdrop-filter:blur(3px);-webkit-backdrop-filter:blur(3px)}
 .loginbox p{font-size:14px;margin:0 0 8px}
 .loginbox input[type=text]{padding:8px 10px;margin:3px 0 8px}
 .loginbox .btn{padding:9px 18px}
 .loginbox .note{margin-top:6px}
}
/* ===== BATTLE SCREEN: clear sides, fits one screen ===== */
body.inbattle header{display:none}
body.inbattle #tab-battle{padding-top:6px}
body.inbattle #app .wrap{padding-bottom:6px}
body.inbattle .arena{margin-top:0}
.arena{--cw:clamp(110px,calc((100vh - 360px) / 2.7),170px);padding:6px 10px}
.agrid{display:grid;grid-template-columns:auto minmax(300px,440px);gap:16px;align-items:start;justify-content:center}
.board{display:flex;flex-direction:column;gap:6px}
.arena .brow3{grid-template-columns:repeat(3,var(--cw));max-width:none;margin:0;justify-content:center}
.zone{border-radius:14px;padding:4px 10px 4px}
.zone.op{background:rgba(229,72,77,.12);border:2px solid rgba(242,125,112,.55)}
.zone.me{background:rgba(70,140,240,.13);border:2px solid rgba(120,175,255,.6)}
.zlab{font-weight:800;font-size:14px;letter-spacing:.12em;text-align:center;margin-bottom:3px}
.zone.op .zlab{color:#ffb0a6}.zone.me .zlab{color:#a9cdff}
.vsline{display:flex;align-items:center;gap:10px;min-height:30px}
.vs{flex:none;font:800 18px Palatino,Georgia,serif;letter-spacing:.1em;color:#1a0f08;background:linear-gradient(180deg,#e98a30,#c8661a);border-radius:99px;padding:3px 12px;box-shadow:0 0 12px rgba(224,122,31,.5)}
.vsline .bmsg{flex:1;min-height:0;margin:0;text-align:left;line-height:1.25}
.side{display:flex;flex-direction:column;gap:8px}
.turnline{font-size:16px}
.side .acts{justify-content:flex-start;margin:0}
.side .qbox{max-width:none;margin:0}
.qbox .choice{margin:0}
.qbox .q{margin:2px 0 10px}
.qbox{display:flex;flex-wrap:wrap;align-items:center;gap:0 10px}
.qbox .q,.qbox .qchoices{flex:0 0 100%}
.qbox .fb{flex:1;margin:8px 0}
.qbox #bCont{margin:8px 0}
.qchoices{display:grid;grid-template-columns:1fr 1fr;gap:8px}
@media(max-width:899px){
 .agrid{grid-template-columns:1fr}
 .arena{--cw:clamp(100px,min(calc((100vh - 660px) / 2.7),calc((100vw - 80px) / 3)),170px)}
 .side .acts{justify-content:center}
 .side{flex-direction:row;flex-wrap:wrap;align-items:center;column-gap:12px}
 .side>.turnline{order:-1;flex:1 1 auto}
 .side>.abar{flex:0 0 auto;gap:12px}
 .side>.acts,.side>.qbox{flex:0 0 100%}
 .qbox .choice{padding:8px 12px;line-height:1.3}
 .qbox .q{font-size:17px!important;margin:0 0 8px}
 .qchoices{gap:6px}
}

/* ===== QUESTION PICKER ===== */
.qset{margin:6px 0 12px}
.qset label{display:block;margin-bottom:4px}
.qset select{font:inherit;font-size:16px;width:100%;max-width:420px;padding:10px 12px;border-radius:8px;background:#0f0b17;color:#ece6f5;border:1px solid #3d2f57}
.qset select:focus{outline:none;border-color:#e07a1f;box-shadow:0 0 0 3px rgba(224,122,31,.2)}
/* ===== SPELLING (listen and type) ===== */
.spk{display:inline-flex;align-items:center;gap:8px;font:inherit;font-size:17px;font-weight:700;padding:10px 16px;margin:8px 0 2px;border-radius:99px;border:1px solid #f2a24f;background:linear-gradient(180deg,#e98a30,#c8661a);color:#1a0f08;cursor:pointer}
.typerow{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:8px 0;flex:0 0 100%}
.typein{font:inherit;font-size:20px;flex:1 1 180px;max-width:320px;padding:10px 12px;border-radius:8px;background:#0f0b17;color:#ece6f5;border:1px solid #3d2f57}
.typein:focus{outline:none;border-color:#e07a1f;box-shadow:0 0 0 3px rgba(224,122,31,.2)}
.typein.right{border-color:#4fbf7a;background:#123321}.typein.wrong{border-color:#f27d70;background:#3a1814}

body.script:
//

/* ================= SETTINGS ================= */
// Paste the Google Apps Script web-app URL between the quotes to turn on saving across devices.
// Leave it empty and progress saves only in this browser.
const SAVE_URL = "https://script.google.com/macros/s/AKfycbzRg-Se6qzIHU6Rg4esGyiVVeOW76Ohd5HpWW6g3NlfL2wi3MgimMvgNBSmIbpWAtX_/exec";

/* ================= QUESTIONS (swap this list each week) =================
   Each row: [question, correct answer, wrong 1, wrong 2, wrong 3] */
// Math set: new problems are made every round (3 addition, 3 subtraction, 3 make a ten, 3 comparing).
function rint(a,b){return a+Math.floor(Math.random()*(b-a+1))}
function nearWrong(ans,lo,hi){const w=[];const d=shuffle([-3,-2,-1,1,2,3]);for(const x of d){const v=ans+x;if(v>=lo&&v<=hi&&w.length<3)w.push(String(v))}return w}
function mathQs(){
  const rows=[], seen={};
  function add(make){for(let t=0;t<50;t++){const r=make();if(!seen[r[0]]){seen[r[0]]=1;rows.push(r);return}}}
  for(let i=0;i<3;i++) add(()=>{const a=rint(1,9),b=rint(1,9);return ["What is "+a+" + "+b+"?",String(a+b)].concat(nearWrong(a+b,0,20))});
  for(let i=0;i<3;i++) add(()=>{const a=rint(9,18),b=rint(2,9),c=a-b;return ["What is "+a+" - "+b+"?",String(c)].concat(nearWrong(c,0,18))});
  for(let i=0;i<3;i++) add(()=>{const a=rint(0,10),c=10-a;return ["You have "+a+". How many more make 10?",String(c)].concat(nearWrong(c,0,10))});
  for(let i=0;i<3;i++) add(()=>{let a=rint(10,30),b=rint(10,30);while(b===a)b=rint(10,30);return ["Which number is bigger: "+a+" or "+b+"?",String(Math.max(a,b)),String(Math.min(a,b))]});
  return rows;
}
const QUESTION_SETS = [
 {key:"beetles", label:"2nd Grade Vocab: Beetles", q:[
["to act in a certain way", "behave", "express", "flapping", "rhyme"],
["moving up and down", "flapping", "behave", "feathers", "rhythm"],
