];
// The picked set is remembered on this device. "beetles" (this week) is the default.
// The storage name changed to "badmascots_qset3" so every device starts on this week once.
let SET_KEY = (()=>{try{const k=localStorage.getItem("badmascots_qset3");if(QUESTION_SETS.some(x=>x.key===k))return k}catch(e){}return "beetles"})();
function curSet(){return QUESTION_SETS.find(x=>x.key===SET_KEY)||QUESTION_SETS[0]}
// Spelling sets: "listen" = hear the word and pick the spelling, "type" = hear the word and type it.
function qMode(){return curSet().mode||""}
function speak(w){try{const s=window.speechSynthesis;if(!s)return;s.cancel();const u=new SpeechSynthesisUtterance(w);u.lang="en-US";u.rate=0.8;s.speak(u)}catch(e){}}
function qText(row,style){
  const m=qMode();
  if(!m) return '<div class="q"'+(style||"")+'>'+esc(row[0])+'</div>';
  return '<div class="q"'+(style||"")+'>'+(m==="type"?"Listen, then type the word.":"Listen, then pick the right spelling.")+
    '<br><button class="spk" type="button">&#128264; Hear the word</button></div>';
}
function normWord(t){return String(t||"").toLowerCase().replace(/\s+/g,"")}
function typeBox(answered,ok,typed){
  return '<div class="typerow"><input class="typein'+(answered?(ok?" right":" wrong"):"")+'" id="typeIn" type="text" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" placeholder="Type the word"'+
    (answered?' value="'+esc(typed||"")+'" disabled':'')+'>'+(answered?'':'<button class="btn" id="typeGo" type="button">Check</button>')+'</div>';
}
function wireSpell(word,onCheck){
  document.querySelectorAll(".spk").forEach(b=>b.onclick=()=>speak(word));
  const inp=$("#typeIn"), go=$("#typeGo");
  if(inp&&go){ go.onclick=()=>onCheck(inp.value); inp.onkeydown=e=>{if(e.key==="Enter"){e.preventDefault();onCheck(inp.value)}}; }
}
let WEEK_LABEL = curSet().label;
let QUESTIONS = curSet().q;
function freshQ(){const s=curSet();if(s.gen){QUESTIONS=s.gen();BATTLE_QUESTIONS=QUESTIONS}return QUESTIONS}

/* ================= CARDS ================= */
