// price label position on each pack picture (percent of picture) and text color
const PACKTAG = {cheap:{l:23.4,t:67.4,w:54.2,h:8.3,c:"#ff9a3c"},standard:{l:23.7,t:68.8,w:52.6,h:9.0,c:"#e3e8ee"},premium:{l:22.7,t:70.1,w:55.5,h:9.7,c:"#f2c14e"}};
const STATS = {"card-01": [2, 1, 1], "card-02": [1, 2, 1], "card-03": [1, 1, 2], "card-04": [4, 2, 2], "card-05": [6, 7, 2], "card-06": [2, 1, 1], "card-07": [1, 2, 1], "card-08": [3, 3, 1], "card-09": [7, 5, 2], "card-10": [1, 2, 1], "card-11": [2, 2, 1], "card-12": [2, 4, 2], "card-13": [1, 5, 1], "card-14": [6, 6, 2], "card-15": [2, 3, 2], "card-16": [4, 2, 1], "card-17": [2, 2, 1], "card-18": [2, 1, 1], "card-19": [2, 2, 1], "card-20": [1, 2, 1], "card-21": [3, 4, 1], "card-22": [7, 7, 2], "card-23": [3, 3, 2], "card-24": [4, 3, 1], "card-25": [2, 1, 1], "card-26": [4, 3, 1], "card-27": [3, 4, 1], "card-28": [2, 4, 2], "card-29": [4, 2, 2], "card-30": [4, 3, 1], "card-31": [5, 7, 2], "card-32": [1, 2, 1], "card-33": [2, 1, 2], "card-34": [4, 3, 1], "card-35": [2, 1, 2], "card-36": [3, 5, 1], "card-37": [7, 6, 2],
"card-38": [4, 3, 1],
