// extra-hard cards: 1 = normal chance, 0.25 = one-fourth the chance of the other cards of its rarity
const HARD = {"card-22": 0.25}; // [Attack, Health, Upgrade]
const IMGS = {"card-01": "data:image/webp;base64,", "card-02": "data:image/webp;base64,", "card-03": "data:image/webp;base64,", "card-04": "data:image/webp;base64,", "card-05": "data:image/webp;base64,", "card-06": "data:image/webp;base64,", "card-07": "data:image/webp;base64,", "card-08": "data:image/webp;base64,", "card-09": "data:image/webp;base64,", "card-10": "data:image/webp;base64,", "card-11": "data:image/webp;base64,", "card-12": "data:image/webp;base64,", "card-13": "data:image/webp;base64,", "card-14": "data:image/webp;base64,", "card-15": "data:image/webp;base64,", "card-16": "data:image/webp;base64,", "card-17": "data:image/webp;base64,", "card-18": "data:image/webp;base64,", "card-19": "data:image/webp;base64,", "card-20": "data:image/webp;base64,", "card-21": "data:image/webp;base64,", "card-22": "data:image/webp;base64,", "card-23": "data:image/webp;base64,", "card-24": "data:image/webp;base64,", "card-25": "data:image/webp;base64,", "card-26": "data:image/webp;base64,", "card-27": "data:image/webp;base64,", "card-28": "data:image/webp;base64,", "card-29": "data:image/webp;base64,", "card-30": "data:image/webp;base64,", "card-31": "data:image/webp;base64,", "card-32": "data:image/webp;base64,", "card-33": "data:image/webp;base64,", "card-34": "data:image/webp;base64,", "card-35": "data:image/webp;base64,", "card-36": "data:image/webp;base64,", "card-37": "data:image/webp;base64,",
