"card-41": "data:image/webp;base64,"};

/* ================= STATE + SAVING ================= */
const $ = s=>document.querySelector(s);
let S = null;               // {id,name,tokens,cards,correct,updated}
let saveTimer = null;

function esc(t){return String(t).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]))}
function normId(v){return String(v||"").trim().toLowerCase()}
function lkey(id){return "monstercards_"+id}
function readLocal(id){try{const r=localStorage.getItem(lkey(id));return r?JSON.parse(r):null}catch(e){return null}}
function writeLocal(){try{localStorage.setItem(lkey(S.id),JSON.stringify(S))}catch(e){}}
function setSave(msg,err){const el=$("#saveMsg");el.textContent=msg;el.className="save"+(err?" err":"")}

function changed(){
  S.updated = Date.now();
  writeLocal();
  $("#tok").textContent = S.tokens;
  if(!SAVE_URL){setSave("Saved on this device only");return}
  setSave("Saving…");
  clearTimeout(saveTimer);
  saveTimer = setTimeout(pushSave,700);
}
function pushSave(){
  if(!SAVE_URL||!S)return;
  const snap = {action:"save",id:S.id,name:S.name,tokens:S.tokens,cards:S.cards,correct:S.correct,updated:S.updated,rp:S.rp||0,w:S.w||0,l:S.l||0};
  fetch(SAVE_URL,{method:"POST",mode:"no-cors",headers:{"Content-Type":"text/plain;charset=utf-8"},body:JSON.stringify(snap)})
   .then(()=>setTimeout(()=>verifySave(snap),1500))
   .catch(()=>setSave("Could not reach the save server. Your progress is kept on this device.",true));
}
// The browser cannot see the result of a save, so read it back to confirm the server really has it.
async function verifySave(snap){
  if(!S||S.id!==snap.id||S.updated!==snap.updated)return;   // a newer change is already on its way
  const r = await loadRemote(snap.id);
  if(!S||S.updated!==snap.updated)return;
  if(r.ok && r.rec && +r.rec.updated===snap.updated) setSave("Saved to the server");
  else setSave("NOT saved to the server yet. Your progress is kept on this device. Try again in a minute.",true);
}
async function loadRemote(id){
  if(!SAVE_URL)return {ok:true,rec:null};
  const ctl = new AbortController(); const t=setTimeout(()=>ctl.abort(),9000);
  try{
    const r = await fetch(SAVE_URL+"?action=load&id="+encodeURIComponent(id),{signal:ctl.signal});
    const j = await r.json(); clearTimeout(t);
    return {ok:true,rec:(j&&j.found)?j:null};
  }catch(e){clearTimeout(t);return {ok:false,rec:null}}
}

async function login(){
  const id = normId($("#idIn").value), nm = $("#nameIn").value.trim();
  const msg = $("#loginMsg");
  if(!id){msg.textContent="Please create a player ID.";return}
  $("#goBtn").disabled = true; msg.textContent = "Loading your cards…";
  const loc = readLocal(id);
  const rem = await loadRemote(id);
  let rec = null;
  if(SAVE_URL && !rem.ok){msg.textContent="Could not reach the save server, so your cards were not loaded. Wait a few seconds and press Start again.";$("#goBtn").disabled=false;return}
  if(loc && rem.rec){ const lc=+loc.correct||0, rc=+rem.rec.correct||0;
    rec = lc!==rc ? (rc>lc ? rem.rec : loc) : ((rem.rec.updated||0) >= (loc.updated||0) ? rem.rec : loc); }
  else rec = rem.rec || loc;
  if(!rec && !nm){msg.textContent="First time here? Please type your first name too.";$("#goBtn").disabled=false;return}
  S = rec ? {id,name:rec.name||nm,tokens:+rec.tokens||0,cards:rec.cards||{},correct:+rec.correct||0,updated:rec.updated||Date.now()}
          : {id,name:nm,tokens:0,cards:{},correct:0,updated:Date.now()};
  if(nm && !rec) S.name = nm;
  const mx=k=>Math.max(+(loc&&loc[k])||0,+(rem.rec&&rem.rec[k])||0);
  S.rp=mx("rp"); S.w=mx("w"); S.l=mx("l");
  $("#login").classList.add("hide"); $("#app").classList.remove("hide");
  $("#who").textContent = S.name+" ("+S.id+")";
  $("#tok").textContent = S.tokens;
  if(SAVE_URL && !rem.ok) setSave("Could not reach the save server. Using the copy on this device.",true);
  else if(SAVE_URL) {setSave("Connected to the save server");pushSave()}
  else setSave("Saved on this device only");
  writeLocal();
  show("play"); renderPlay();
  $("#goBtn").disabled=false; msg.textContent="";
}
function logout(){ battleReset(); if(S){clearTimeout(saveTimer);pushSave()} S=null; $("#app").classList.add("hide"); $("#login").classList.remove("hide"); $("#idIn").value="";$("#nameIn").value="" }

/* ================= TABS ================= */
function show(t){
  document.querySelectorAll("nav button").forEach(b=>b.classList.toggle("on",b.dataset.t===t));
  ["play","packs","coll","battle","board"].forEach(x=>$("#tab-"+x).classList.toggle("hide",x!==t));
  if(t==="packs")renderPacks(); if(t==="coll")renderColl(); if(t==="battle")renderBattle(); if(t==="board")renderBoard();
}

/* ================= QUIZ ================= */
let run = null;
function shuffle(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function setPicker(){
  return '<div class="qset"><label for="qset">Pick your questions</label><select id="qset">'+
    QUESTION_SETS.map(x=>'<option value="'+x.key+'"'+(x.key===SET_KEY?' selected':'')+'>'+esc(x.label)+'</option>').join("")+'</select></div>';
}
function wirePicker(){
  const sel=$("#qset"); if(!sel)return;
  sel.onchange=()=>{SET_KEY=sel.value; try{localStorage.setItem("badmascots_qset3",SET_KEY)}catch(e){}
    WEEK_LABEL=curSet().label; QUESTIONS=curSet().q; BATTLE_QUESTIONS=QUESTIONS; run=null; renderPlay()};
}
function renderPlay(){
  const el = $("#tab-play");
  if(!run){
    el.innerHTML = '<div class="panel">'+setPicker()+'<h2>'+esc(WEEK_LABEL)+' Questions</h2>'+
      '<p>Each correct answer earns <b>1 token</b>. A wrong answer earns nothing, and the right answer is shown.</p>'+
      '<p class="mute">'+(curSet().gen?'Each round has '+QUESTIONS.length+' new problems. You can play as many rounds as you want.':'There are '+QUESTIONS.length+' questions. You can play them again as many times as you want. They are shuffled each time.')+'</p>'+
      '<button class="btn" id="startQ">Start</button></div>';
    $("#startQ").onclick = ()=>{run={order:shuffle(freshQ()),i:0,right:0,done:false,picked:null};renderPlay()};
    wirePicker();
    return;
  }
  if(run.i>=run.order.length){
    el.innerHTML = '<div class="panel"><h2>Finished</h2><div class="stats"><div><b>'+run.right+' of '+run.order.length+'</b>correct this round</div><div><b>+'+run.right+'</b>tokens earned</div></div>'+
      '<p>You now have <b>'+S.tokens+'</b> tokens.</p>'+
      setPicker()+'<button class="btn" id="again">Play again</button> <button class="btn alt" id="toPacks">Go to card packs</button></div>';
    $("#again").onclick=()=>{run={order:shuffle(freshQ()),i:0,right:0,done:false,picked:null};renderPlay()};
    $("#toPacks").onclick=()=>{run=null;show("packs")};
    wirePicker();
    return;
  }
  const q = run.order[run.i], mode = qMode();
  if(!run.choices) run.choices = shuffle(q.slice(1));
  const answered = run.picked!==null;
  let h = '<div class="panel"><div class="prog"><i style="width:'+(run.i/run.order.length*100)+'%"></i></div>'+
    '<div class="mute">Question '+(run.i+1)+' of '+run.order.length+'</div>'+qText(q);
  if(mode==="type"){
    h += typeBox(answered,run.ok,run.typed);
  } else run.choices.forEach((c,k)=>{
    let cls="choice";
    if(answered){ if(c===q[1])cls+=" right"; else if(k===run.picked)cls+=" wrong" }
    h += '<button class="'+cls+'" data-k="'+k+'" '+(answered?"disabled":"")+'>'+esc(c)+'</button>';
  });
  if(answered){
    const ok = run.ok;
    h += '<div class="fb '+(ok?"good":"bad")+'">'+(ok?"Correct! +1 token":(mode==="type"?"Not quite. The word is spelled: <b>"+esc(q[1])+"</b>":"Not quite. The correct answer is highlighted in green."))+'</div>'+
         '<button class="btn" id="nextQ">'+(run.i+1<run.order.length?"Next question":"See results")+'</button>';
  }
  el.innerHTML = h+'</div>';
  el.querySelectorAll(".choice").forEach(b=>b.onclick=()=>pick(+b.dataset.k));
  wireSpell(q[1],t=>{ if(!normWord(t))return; run.typed=t; pick(normWord(t)===normWord(q[1])?-1:-2); });
  if(mode&&!answered&&run.spoken!==run.i){ run.spoken=run.i; speak(q[1]); }
  const n=$("#nextQ"); if(n) n.onclick=()=>{run.i++;run.choices=null;run.picked=null;run.typed="";renderPlay();window.scrollTo(0,0)};
}
function pick(k){
  if(run.picked!==null)return;
  run.picked = k;
  const q = run.order[run.i];
  // k = -1 / -2 means a typed answer that was right / wrong
  run.ok = k===-1 || (k>=0 && run.choices[k]===q[1]);
  if(run.ok){ S.tokens++; S.correct++; run.right++; changed(); }
  renderPlay();
}

/* ================= PACKS ================= */
function rollRarity(odds){
  const r = Math.random()*100; let acc=0;
  for(const k of ["common","rare","legendary"]){acc+=odds[k]; if(r<acc)return k}
  return "common";
}
function rollCard(pack){
  const rar = rollRarity(pack.odds);
  const pool = CARDS.filter(c=>c[2]===rar);
  // some cards are extra hard to get: they come up less often than others of the same rarity
  const wt = c => (HARD[c[0]]||1);
  let r = Math.random()*pool.reduce((t,c)=>t+wt(c),0);
  for(const c of pool){ r -= wt(c); if(r < 0) return c; }
  return pool[pool.length-1];
}
function renderPacks(){
  let h = '<div class="panel"><h2>Card Packs</h2><p>Each pack has <b>1 card</b>. Pricier packs give better odds of a rare or legendary card. You have <b>'+S.tokens+'</b> tokens.</p><div class="packs">';
  PACKS.forEach(p=>{
    const tg=PACKTAG[p.key];
    h += '<div class="pack"><div class="pk"><img alt="'+p.name+'" src="'+PACKIMG[p.key]+'"><span class="ptag" style="left:'+tg.l+'%;top:'+tg.t+'%;width:'+tg.w+'%;height:'+tg.h+'%;color:'+tg.c+'">'+p.cost+' TOKENS</span></div><h3>'+p.name+'</h3><div class="cost">'+p.cost+' tokens</div>'+
      '<div class="odds">Common '+p.odds.common+'%<br>Rare '+p.odds.rare+'%<br>Legendary '+p.odds.legendary+'%</div>'+
      '<button class="btn" data-p="'+p.key+'" '+(S.tokens<p.cost?"disabled":"")+'>Open pack</button></div>';
  });
  h += '</div><div class="note">Not enough tokens? Answer more questions. Duplicates can be sold back in My Collection.</div></div>';
  $("#tab-packs").innerHTML = h;
  document.querySelectorAll("#tab-packs [data-p]").forEach(b=>b.onclick=()=>openPack(b.dataset.p));
}
const SWORD='<svg viewBox="0 0 24 24"><path d="M4 20l3-1 9-9 3-6-6 3-9 9-1 3z" fill="#e9edf2" stroke="#3a3f47" stroke-width="1.6" stroke-linejoin="round"/><path d="M6.5 17.5l-2.5 2.5M10 14l-3-3" stroke="#3a3f47" stroke-width="1.6" stroke-linecap="round"/></svg>';
const HEART='<svg viewBox="0 0 24 24"><path d="M12 21s-8-5.2-8-11a4.6 4.6 0 018-3 4.6 4.6 0 018 3c0 5.800-8 11-8 11z" fill="#e5484d" stroke="#7a1f23" stroke-width="1.6" stroke-linejoin="round"/></svg>';
function frameHtml(c,extra,ov){
  const t = ov||STATS[c[0]]||[0,0,0];
  return '<div class="frame '+c[2]+'">'+(extra||"")+'<div class="inner"><div class="nm">'+esc(c[1])+'</div><img alt="'+esc(c[1])+'" src="'+IMGS[c[0]]+'">'+
    '<div class="st"><span class="pill">'+SWORD+t[0]+'</span><span class="up"><i>UPGRADE</i><b>+'+t[2]+'</b></span><span class="pill r">'+t[1]+HEART+'</span></div></div></div>';
}
function openPack(key,free,onClose){
  const p = PACKS.find(x=>x.key===key);
  if(!free&&S.tokens<p.cost)return;
  if(!free)S.tokens -= p.cost;
  const c = rollCard(p);
  const had = S.cards[c[0]]||0;
  S.cards[c[0]] = had+1;
  changed();
  const box = $("#modalBox");
  let sp=''; const n=c[2]==="legendary"?34:(c[2]==="rare"?20:10);
  for(let k=0;k<n;k++){const an=Math.random()*6.283,d=110+Math.random()*90;sp+='<i class="sp" style="--x:'+Math.round(Math.cos(an)*d)+'px;--y:'+Math.round(Math.sin(an)*d)+'px"></i>'}
  box.innerHTML = '<div class="stage '+c[2]+'"><div class="flash"></div><div class="fx">'+sp+'</div><div class="cardwrap">'+frameHtml(c)+'</div>'+
    '<div class="pk2"><img class="pbody" alt="" src="'+PACKIMG[p.key]+'"><img class="ptop" alt="" src="'+PACKIMG[p.key]+'"></div></div>'+
    '<div class="reveal-info"><div class="rar '+c[2]+'">'+c[2]+'</div>'+
    '<div class="badge '+(had?"dup":"new")+'">'+(had?"Duplicate. You now have "+(had+1):"New card!")+'</div><div><button class="btn" id="mClose" disabled>OK</button></div></div>';
  $("#modal").onclick=null;
  $("#modal").classList.remove("hide");
  $("#mClose").onclick = ()=>{ $("#modal").classList.add("hide"); (onClose||renderPacks)(); };
  setTimeout(()=>{const m=$("#mClose"); if(m) m.disabled=false},2800);
}

/* ================= COLLECTION ================= */
let sellArm = null;
function renderColl(){
  const owned = CARDS.filter(c=>S.cards[c[0]] > 0).length;
  let h = '<div class="panel"><h2>My Collection</h2><div class="stats"><div><b>'+owned+' of '+CARDS.length+'</b>cards collected</div><div><b>'+S.tokens+'</b>tokens</div></div>'+
    '<div class="note">Sell values: common '+SELL.common+', rare '+SELL.rare+', legendary '+SELL.legendary+' tokens. Selling removes one copy.</div><div class="grid">';
  CARDS.forEach((c,i)=>{
    const n = S.cards[c[0]]||0;
    if(n>0){
      const armed = sellArm===c[0];
      h += '<div class="slot">'+frameHtml(c,n>1?'<span class="cnt">×'+n+'</span>':"")+
        '<div class="rar '+c[2]+'">'+c[2]+'</div>'+
        '<button class="btn alt sell" data-s="'+c[0]+'">'+(armed?"Tap again to sell for "+SELL[c[2]]:"Sell one for "+SELL[c[2]])+'</button></div>';
    } else {
      h += '<div class="slot"><div class="frame empty"><div class="blank">?</div></div><div class="cn mute">Card '+(i+1)+'</div><div class="rar '+c[2]+'">'+c[2]+'</div></div>';
    }
  });
  $("#tab-coll").innerHTML = h+'</div></div>';
  document.querySelectorAll("#tab-coll [data-s]").forEach(b=>b.onclick=()=>sell(b.dataset.s));
}
function sell(id){
  const c = CARDS.find(x=>x[0]===id);
  if(!c||!(S.cards[id]>0))return;
  if(sellArm!==id){sellArm=id;renderColl();return}
  sellArm=null;
  S.cards[id]--; if(S.cards[id]<=0)delete S.cards[id];
  S.tokens += SELL[c[2]];
  changed(); renderColl();
}

/* ================= SCOREBOARD (Top Collectors) ================= */
const CARD_BY_ID = {}; CARDS.forEach(c=>CARD_BY_ID[c[0]]=c);
let boardTok = 0;
function ptsOf(cards){let p=0,n=0;for(const k in cards){const c=CARD_BY_ID[k];if(c&&cards[k]>0){p+=SELL[c[2]];n++}}return {p,n}}
function ownedSorted(cards){
  const order={legendary:0,rare:1,common:2};
  return Object.keys(cards).filter(k=>CARD_BY_ID[k]&&cards[k]>0).map(k=>CARD_BY_ID[k])
    .sort((a,b)=>order[a[2]]-order[b[2]]||a[0].localeCompare(b[0]));
}
async function renderCollectors(){
  const el=$("#tab-board"), my=++boardTok;
  el.innerHTML='<div class="panel">'+boardTabs()+'<h2>Top Collectors</h2><div class="note" style="margin:0 0 10px">Points: common '+SELL.common+', rare '+SELL.rare+', legendary '+SELL.legendary+'. Each different card counts once. Tap a small card to see it bigger.</div>'+
    '<button class="btn alt" id="bRef">Refresh</button><div id="bList" class="mute" style="margin-top:12px">Loading the scoreboard…</div></div>';
  $("#bRef").onclick=renderBoard;
  const list=$("#bList");
  if(!SAVE_URL){list.textContent="The scoreboard needs the save server to be turned on.";return}
  let players=null;
  const ctl=new AbortController(); const to=setTimeout(()=>ctl.abort(),12000);
  try{
    const r=await fetch(SAVE_URL+"?action=board&id="+encodeURIComponent(S.id),{signal:ctl.signal});
    const j=await r.json(); clearTimeout(to);
    if(j&&Array.isArray(j.players)) players=j.players;
  }catch(e){clearTimeout(to)}
  if(my!==boardTok)return;
  if(!players){list.innerHTML='<span style="color:var(--bad)">Could not load the scoreboard right now. Tap Refresh to try again.</span>';return}
  // your own row always uses your latest local progress
  players=players.filter(p=>!p.you);
  players.push({name:S.name,cards:S.cards,you:true});
  const rows=players.map(p=>{const s=ptsOf(p.cards||{});return {name:String(p.name||"?"),cards:p.cards||{},you:!!p.you,pts:s.p,n:s.n}})
    .filter(r=>r.n>0).sort((a,b)=>b.pts-a.pts||b.n-a.n||a.name.localeCompare(b.name));
  if(!rows.length){list.textContent="No cards collected yet. Be the first!";return}
  let h="", rank=0;
  rows.forEach((r,i)=>{
    if(i===0||r.pts!==rows[i-1].pts)rank=i+1;
    const own=ownedSorted(r.cards), star=own.some(c=>c[2]==="legendary");
    h+='<div class="brow'+(r.you?' me':'')+'"><div class="bhead"><div class="rk'+(rank<=3?' g'+rank:'')+'">'+rank+'</div>'+
       '<div class="bn">'+esc(r.name)+(r.you?' (you)':'')+(star?' <span style="color:#c8921a" title="Owns a legendary card">★</span>':'')+'</div>'+
       '<div class="bp"><b>'+r.pts+'</b> <span>pts · '+r.n+' of '+CARDS.length+'</span></div></div><div class="mini">'+
       own.map(c=>'<button class="mc '+c[2]+'" data-id="'+c[0]+'" aria-label="'+esc(c[1])+'"><span class="mi"><img alt="" src="'+IMGS[c[0]]+'"><b class="ms">'+(STATS[c[0]]||[0,0])[0]+'/'+(STATS[c[0]]||[0,0])[1]+'</b></span></button>').join("")+
       '</div><div class="mcap"></div></div>';
  });
  list.className=""; list.innerHTML=h;
  list.querySelectorAll(".mc").forEach(b=>b.onclick=()=>{
    const c=CARD_BY_ID[b.dataset.id]; if(!c)return;
    $("#modalBox").innerHTML='<div style="width:min(300px,78vw);margin:0 auto">'+frameHtml(c)+'</div><div class="rar '+c[2]+'" style="margin-top:8px">'+c[2]+'</div><div style="margin-top:6px"><button class="btn" id="mClose2">Close</button></div>';
    $("#modal").classList.remove("hide");
    const close=()=>{$("#modal").classList.add("hide");$("#modal").onclick=null};
    $("#mClose2").onclick=close;
    $("#modal").onclick=e=>{if(e.target.id==="modal")close()};
  });
}

/* ================= BATTLE ================= */
// Tunable numbers. Rank points, boss chance and AI accuracy are first guesses, easy to change here.
const BATTLE = {MOVES:2, BOSS_CHANCE:0.12, AI_RIGHT:0.8, AI_UPGRADE:0.35, WIN_RP:10, BOSS_WIN_RP:20, PRIZE:"cheap"};
let BATTLE_QUESTIONS = QUESTIONS;
let B = null, bTok = 0, deckSel = [], lastDeck = [];
const sleep = ms=>new Promise(r=>setTimeout(r,ms));
function battleReset(){bTok++;B=null;deckSel=[];lastDeck=[];document.body.classList.remove("inbattle")}
function mk(c){const t=STATS[c[0]];return {id:c[0],c:c,a:t[0],h:t[1],mh:t[1],u:t[2]}}
function pickRand(a){return a[Math.floor(Math.random()*a.length)]}
function alive(side){return B[side].filter(x=>x.h>0)}

function makeOpp(){
  const boss = Math.random()<BATTLE.BOSS_CHANCE;
  const leg = CARDS.filter(c=>c[2]==="legendary"), rest = CARDS.filter(c=>c[2]!=="legendary");
  const pool = []; rest.forEach(c=>{for(let i=0;i<(c[2]==="common"?2:1);i++)pool.push(c)});
  const d = []; if(boss) d.push(pickRand(leg));
  while(d.length<3){const c=pickRand(pool); if(!d.includes(c))d.push(c)}
  return {cards:shuffle(d).map(mk),boss};
}
function nextQ(){
  if(!B.bag||!B.bag.length) B.bag = shuffle(curSet().gen?curSet().gen():BATTLE_QUESTIONS);
  const row = B.bag.pop();
  return {row:row,choices:shuffle(row.slice(1)),picked:null,ok:false};
}

/* ---- screens ---- */
function renderBattle(){
  document.body.classList.toggle("inbattle", !!B && B.screen==="arena");
  const el = $("#tab-battle");
  if(!B) return renderBMenu(el);
  if(B.screen==="pick") return renderBPick(el);
  if(B.screen==="arena") return renderBArena(el);
  if(B.screen==="end") return renderBEnd(el);
}
function recHtml(){return '<div class="rec"><div><b>'+(S.rp||0)+'</b>rank points</div><div><b>'+(S.w||0)+'</b>wins</div><div><b>'+(S.l||0)+'</b>losses</div></div>'}
function renderBMenu(el){
  deckSel = deckSel.filter(id=>S.cards[id]>0);
  if(!deckSel.length) deckSel = lastDeck.filter(id=>S.cards[id]>0);
  const owned = CARDS.filter(c=>S.cards[c[0]] > 0);
  let h = '<div class="panel"><h2>Battle</h2>'+recHtml()+
    '<ul class="rules"><li>Build a deck of <b>3 different cards</b>. Only <b>1 legendary</b> is allowed.</li>'+
    '<li>Each turn you get <b>2 moves</b>. A move is <b>Attack</b> or <b>Upgrade</b>.</li>'+
    '<li>Attack is free. Upgrade means you answer a question. A right answer adds the card\'s upgrade number to its Attack and Health.</li>'+
    '<li>A wrong answer uses up the move. There is no other penalty.</li>'+
    '<li>Damage stays on a card. A card at 0 Health is out. Knock out all 3 enemy cards to win a free pack.</li></ul></div>';
  if(owned.length<3){
    h += '<div class="panel"><b>You need at least 3 different cards to battle.</b><p class="mute">You have '+owned.length+'. Answer questions to earn tokens, then open packs.</p></div>';
    el.innerHTML = h; return;
  }
  h += '<div class="panel"><h2>Pick your deck</h2><div class="mute" id="dstat"></div><div class="dgrid">';
  owned.forEach(c=>{h += '<button class="dpick" data-id="'+c[0]+'"><span class="tick">✓</span>'+frameHtml(c)+'</button>'});
  h += '</div><div style="margin-top:14px"><button class="btn" id="bStart">Find an opponent</button></div></div>';
  el.innerHTML = h;
  const refresh = ()=>{
    const hasLeg = deckSel.some(id=>CARD_BY_ID[id][2]==="legendary");
    el.querySelectorAll(".dpick").forEach(b=>{
      const id=b.dataset.id, sel=deckSel.includes(id), leg=CARD_BY_ID[id][2]==="legendary";
      b.classList.toggle("sel",sel);
      b.classList.toggle("off",!sel&&((leg&&hasLeg)||deckSel.length>=3));
    });
    $("#dstat").textContent = "Your deck: "+deckSel.length+" of 3"+(hasLeg?" (legendary chosen, no more allowed)":"");
    $("#bStart").disabled = deckSel.length!==3;
  };
  el.querySelectorAll(".dpick").forEach(b=>b.onclick=()=>{
    const id=b.dataset.id, i=deckSel.indexOf(id);
    if(i>=0) deckSel.splice(i,1);
    else if(!b.classList.contains("off")) deckSel.push(id);
    refresh();
  });
  $("#bStart").onclick = startBattle;
  refresh();
}
function startBattle(){
  if(deckSel.length!==3)return;
  lastDeck = deckSel.slice();
  const opp = makeOpp();
  B = {screen:"pick",me:deckSel.map(id=>mk(CARD_BY_ID[id])),op:opp.cards,boss:opp.boss,turn:"me",moves:1,sel:null,mode:null,q:null,hl:null,busy:false,msg:"",bag:null,quit:false,rpGain:0,win:false};
  renderBattle();
}
function oppRow(){return '<div class="brow3">'+B.op.map((x,i)=>'<div>'+frameHtml(x.c,'',[x.a,x.h,x.u])+'</div>').join("")+'</div>'}
function renderBPick(el){
  el.innerHTML = '<div class="panel" style="text-align:center"><span class="btag'+(B.boss?' boss':'')+'">'+(B.boss?'Boss battle':'Opponent')+'</span>'+
    '<h2 style="margin-top:8px">'+(B.boss?'A boss appears!':'Your opponent')+'</h2>'+oppRow()+
    '<p><b>Who goes first?</b></p><div class="acts"><button class="btn" id="bFirst">Go first (1 move on your first turn)</button><button class="btn alt" id="bSecond">Go second (2 moves on your first turn)</button></div>'+
    '<button class="btn alt" id="bBack" style="margin-top:6px">Back to deck</button></div>';
  $("#bFirst").onclick = ()=>beginBattle(true);
  $("#bSecond").onclick = ()=>beginBattle(false);
  $("#bBack").onclick = ()=>{B=null;renderBattle()};
}
function beginBattle(meFirst){
  B.screen="arena"; B.turn=meFirst?"me":"op"; B.moves=1;
  if(meFirst){B.msg="Your turn. Tap one of your cards.";renderBattle()}
  else{renderBattle();oppTurn()}
}
function canPick(i){return B.turn==="me"&&!B.busy&&B.moves>0&&B.me[i].h>0&&B.mode!=="quiz"&&B.mode!=="target"}
function canTarget(side,i){return side==="op"&&B.turn==="me"&&B.mode==="target"&&!B.busy&&B.op[i].h>0}
function cardEl(side,i){
  const x=B[side][i], dead=x.h<=0, h=Math.max(0,x.h), p=Math.max(0,Math.min(100,h/x.mh*100));
  const col=p>60?'#62c98f':(p>30?'#e0a31f':'#e5484d');
  const cls='bc'+(dead?' ko':'')+((side==='me'&&B.sel===i)||(B.hl&&B.hl.side===side&&B.hl.i===i)?' sel':'')+(canTarget(side,i)?' tgt':'')+(side==='me'&&canPick(i)?' pickable':'');
  return '<div class="'+cls+'" data-s="'+side+'" data-i="'+i+'">'+frameHtml(x.c,'',[x.a,h,x.u])+
    '<div class="hp"><i style="width:'+p+'%;background:'+col+'"></i></div><div class="hpt">'+h+' / '+x.mh+'</div>'+(dead?'<div class="kot">KO</div>':'')+'</div>';
}
function pipsHtml(){let s='<span class="pips">';for(let k=0;k<BATTLE.MOVES;k++)s+='<i class="'+(k<B.moves?'':'u')+'"></i>';return s+'</span>'}
function renderBArena(el){
  let h = '<div class="panel arena"><div class="agrid"><div class="board">'+
    '<div class="zone op"><div class="zlab">'+(B.boss?"BOSS'S CARDS":"OPPONENT'S CARDS")+'</div>'+
    '<div class="brow3">'+B.op.map((x,i)=>cardEl('op',i)).join("")+'</div></div>'+
    '<div class="vsline"><span class="vs">VS</span><span class="bmsg" id="bMsg">'+esc(B.msg)+'</span></div>'+
    '<div class="zone me"><div class="zlab">YOUR CARDS ('+esc(S.name)+')</div>'+
    '<div class="brow3">'+B.me.map((x,i)=>cardEl('me',i)).join("")+'</div></div></div>'+
    '<div class="side"><div class="abar"><span><span class="btag'+(B.boss?' boss':'')+'">'+(B.boss?'Boss battle':'Opponent')+'</span></span>'+
    '<button class="btn alt" id="bQuit" style="padding:6px 12px">'+(B.quit?'Tap again to quit':'Quit')+'</button></div>'+
    '<div class="turnline"><b>'+(B.turn==="me"?"Your turn":"Opponent's turn")+'</b> · moves left'+pipsHtml()+'</div>';
  if(B.turn==="me"&&!B.busy&&B.sel!==null&&B.mode===null){
    const u=B.me[B.sel].u;
    h += '<div class="acts"><button class="btn" id="bAtk">Attack</button><button class="btn" id="bUp">Upgrade +'+u+' (answer a question)</button><button class="btn alt" id="bCancel">Cancel</button></div>';
  } else if(B.mode==="target"&&!B.busy){
    h += '<div class="acts"><button class="btn alt" id="bCancel">Cancel</button></div>';
  }
  if(B.mode==="quiz"&&B.q){
    const q=B.q, answered=q.picked!==null;
    h += '<div class="qbox">'+qText(q.row,' style="font-size:18px"');
    if(qMode()==="type") h += typeBox(answered,q.ok,q.typed);
    else { h += '<div class="qchoices">';
    q.choices.forEach((c,k)=>{
      let cls="choice"; if(answered){if(c===q.row[1])cls+=" right"; else if(k===q.picked)cls+=" wrong"}
      h += '<button class="'+cls+'" data-k="'+k+'" '+(answered?"disabled":"")+'>'+esc(c)+'</button>';
    });
    h += '</div>'; }
    if(answered&&q.ok) h += '<div class="fb good">Correct! Upgrading…</div>';
    if(answered&&!q.ok) h += '<div class="fb bad">Not quite.'+(qMode()==="type"?' The word is spelled: <b>'+esc(q.row[1])+'</b>.':'')+' The move is used up.</div><button class="btn" id="bCont">Continue</button>';
    h += '</div>';
  }
  el.innerHTML = h+'</div></div></div>';
  const q=$("#bQuit"); if(q) q.onclick=quitBattle;
  const a=$("#bAtk"); if(a) a.onclick=()=>{B.mode="target";B.msg="Tap an enemy card to hit it.";renderBattle()};
  const u=$("#bUp"); if(u) u.onclick=()=>{B.mode="quiz";B.q=nextQ();B.msg="Answer to upgrade "+B.me[B.sel].c[1]+".";renderBattle()};
  const c=$("#bCancel"); if(c) c.onclick=()=>{B.sel=null;B.mode=null;B.msg="Your turn. Tap one of your cards.";renderBattle()};
  const ct=$("#bCont"); if(ct) ct.onclick=()=>{B.q=null;playerMoveDone()};
  el.querySelectorAll(".qbox .choice").forEach(b=>b.onclick=()=>answerQ(+b.dataset.k));
  if(B.mode==="quiz"&&B.q){ const bq=B.q;
    wireSpell(bq.row[1],t=>{ if(!normWord(t))return; bq.typed=t; answerQ(normWord(t)===normWord(bq.row[1])?-1:-2); });
    if(qMode()&&bq.picked===null&&!bq.spoken){ bq.spoken=true; speak(bq.row[1]); } }
}
function renderBEnd(el){
  el.innerHTML = '<div class="panel" style="text-align:center"><h2>'+(B.win?'You win!':(B.quit?'You quit the battle.':'Defeated.'))+'</h2>'+
    (B.win?'<p>+'+B.rpGain+' rank points. Your prize pack is opening…</p>':'<p class="mute">No penalty. Build a new deck and try again.</p>')+
    recHtml()+'<button class="btn" id="bDone">Back to deck</button></div>';
  $("#bDone").onclick = ()=>{B=null;renderBattle()};
}
function quitBattle(){
  if(!B||B.screen!=="arena")return;
  if(!B.quit){B.quit=true;renderBattle();return}
  bTok++; endBattle(false,true);
}

/* ---- effects ---- */
function elOf(side,i){return document.querySelector('#tab-battle .bc[data-s="'+side+'"][data-i="'+i+'"]')}
function floatTxt(el,txt,cls){
  if(!el)return; const f=document.createElement("span"); f.className="fl "+cls; f.textContent=txt; el.appendChild(f);
  f.animate([{opacity:0,transform:"translate(-50%,10px) scale(.6)"},{opacity:1,transform:"translate(-50%,-6px) scale(1.15)",offset:.25},{opacity:1,transform:"translate(-50%,-30px) scale(1)",offset:.7},{opacity:0,transform:"translate(-50%,-52px) scale(1)"}],{duration:1000,easing:"ease-out"}).onfinish=()=>f.remove();
}
function hitFx(el,txt){
  if(!el)return; const o=document.createElement("div"); o.className="fxo"; o.style.background="rgba(242,60,50,.6)"; el.appendChild(o);
  o.animate([{opacity:1},{opacity:0}],{duration:450}).onfinish=()=>o.remove();
  el.animate([{transform:"translateX(0)"},{transform:"translateX(-9px) rotate(-2deg)"},{transform:"translateX(9px) rotate(2deg)"},{transform:"translateX(-6px)"},{transform:"translateX(6px)"},{transform:"translateX(0)"}],{duration:420});
  floatTxt(el,txt,"dmg");
}
function upFx(el,txt){
  if(!el)return; const o=document.createElement("div"); o.className="fxo"; o.style.background="radial-gradient(circle,rgba(125,255,176,.55),rgba(125,255,176,0) 70%)"; el.appendChild(o);
  o.animate([{opacity:0},{opacity:1,offset:.3},{opacity:0}],{duration:900}).onfinish=()=>o.remove();
  el.animate([{transform:"scale(1)"},{transform:"scale(1.1)",offset:.35},{transform:"scale(1)"}],{duration:700});
  floatTxt(el,txt,"up");
}

/* ---- turn flow ---- */
async function attackAnim(side,ai,ti){
  const tok=bTok, os=side==="me"?"op":"me", a=B[side][ai], f=B[os][ti];
  const ea=elOf(side,ai), ef=elOf(os,ti);
  if(ea&&ef){
    const ra=ea.getBoundingClientRect(), rf=ef.getBoundingClientRect(), dx=rf.left-ra.left, dy=rf.top-ra.top;
    ea.style.zIndex=30;
    ea.animate([{transform:"translate(0,0) scale(1)"},{transform:"translate("+dx*.08+"px,"+dy*.08+"px) scale(1.06)",offset:.25},{transform:"translate("+dx*.82+"px,"+dy*.82+"px) scale(1.15)",offset:.5},{transform:"translate(0,0) scale(1)"}],{duration:640,easing:"ease-in-out"});
    await sleep(320);
    if(tok!==bTok)return false;
    hitFx(ef,"-"+a.a);
    await sleep(430);
  }
  if(tok!==bTok)return false;
  f.h=Math.max(0,f.h-a.a);
  renderBattle(); await sleep(350);
  return tok===bTok;
}
async function upgradeAnim(side,i){
  const tok=bTok, x=B[side][i]; x.a+=x.u; x.h+=x.u; x.mh+=x.u;
  renderBattle();
  upFx(elOf(side,i),"+"+x.u+" / +"+x.u);
  await sleep(850);
  return tok===bTok;
}
function checkEnd(){
  if(!alive("op").length){endBattle(true);return true}
  if(!alive("me").length){endBattle(false);return true}
  return false;
}
async function answerQ(k){
  if(!B||B.busy||!B.q||B.q.picked!==null)return;
  const tok=bTok, q=B.q; q.picked=k; q.ok = k===-1 || (k>=0 && q.choices[k]===q.row[1]);
  if(q.ok){
    B.busy=true; renderBattle(); await sleep(650);
    if(tok!==bTok)return;
    const i=B.sel; B.q=null; B.mode=null;
    if(!(await upgradeAnim("me",i)))return;
    B.busy=false; playerMoveDone();
  } else renderBattle();
}
async function playerAttack(ti){
  const tok=bTok; B.busy=true; const ai=B.sel; B.mode=null; B.msg=B.me[ai].c[1]+" attacks!"; renderBattle();
  if(!(await attackAnim("me",ai,ti)))return;
  B.busy=false; playerMoveDone();
}
function playerMoveDone(){
  B.sel=null; B.mode=null; B.q=null; B.moves--;
  if(checkEnd())return;
  if(B.moves>0){B.msg="Your turn. "+B.moves+" move left. Tap one of your cards.";renderBattle()}
  else{B.turn="op";B.moves=BATTLE.MOVES;oppTurn()}
}
function aiPick(){
  const my=alive("op"), foes=alive("me");
  let best=null;
  my.forEach(a=>foes.forEach(f=>{ if(a.a>=f.h){const sc=f.a*10+f.mh; if(!best||sc>best.sc)best={t:"atk",a:a,f:f,sc:sc}} }));
  if(best) return best;
  if(Math.random()<BATTLE.AI_UPGRADE){
    let u=my[0]; my.forEach(x=>{if(x.u>u.u||(x.u===u.u&&x.a>u.a))u=x}); return {t:"up",a:u};
  }
  let a=my[0]; my.forEach(x=>{if(x.a>a.a)a=x});
  let f=foes[0]; foes.forEach(x=>{if(x.h<f.h)f=x});
  return {t:"atk",a:a,f:f};
}
async function oppTurn(){
  const tok=bTok; B.turn="op"; B.busy=true; B.sel=null; B.mode=null; B.msg="Opponent's turn…"; renderBattle();
  await sleep(900);
  while(B.moves>0){
    if(tok!==bTok)return;
    const act=aiPick(), ai=B.op.indexOf(act.a);
    B.hl={side:"op",i:ai};
    if(act.t==="atk"){
      B.msg=act.a.c[1]+" attacks!"; renderBattle(); await sleep(500);
      if(tok!==bTok)return;
      if(!(await attackAnim("op",ai,B.me.indexOf(act.f))))return;
    } else {
      const ok=Math.random()<BATTLE.AI_RIGHT;
      B.msg=act.a.c[1]+" tries to upgrade…"; renderBattle(); await sleep(1100);
      if(tok!==bTok)return;
      if(ok){B.msg="The opponent answered right!"; if(!(await upgradeAnim("op",ai)))return}
      else{B.msg="The opponent missed the question."; renderBattle(); await sleep(900)}
    }
    if(tok!==bTok)return;
    B.hl=null; B.moves--;
    if(checkEnd())return;
  }
  B.turn="me"; B.moves=BATTLE.MOVES; B.busy=false; B.sel=null; B.mode=null; B.hl=null;
  B.msg="Your turn. Tap one of your cards."; renderBattle();
}
function endBattle(win,quit){
  B.screen="end"; B.win=!!win; B.busy=false; B.hl=null;
  if(win){B.rpGain=B.boss?BATTLE.BOSS_WIN_RP:BATTLE.WIN_RP; S.rp=(S.rp||0)+B.rpGain; S.w=(S.w||0)+1}
  else S.l=(S.l||0)+1;
  changed(); renderBattle();
  if(win){
    const tok=bTok, sid=S.id;
    setTimeout(()=>{ if(tok!==bTok||!S||S.id!==sid)return; openPack(BATTLE.PRIZE,true,()=>{renderBattle()}) },1400);
  }
}

/* ================= SCOREBOARD (Top Fighters) ================= */
let boardMode = "coll";
function boardTabs(){
  return '<div class="tabs2"><button class="btn alt'+(boardMode==="coll"?" on":"")+'" data-bm="coll">Top Collectors</button><button class="btn alt'+(boardMode==="fight"?" on":"")+'" data-bm="fight">Top Fighters</button></div>';
}
function renderBoard(){
  if(boardMode==="fight") renderFighters(); else renderCollectors();
  document.querySelectorAll("#tab-board [data-bm]").forEach(b=>b.onclick=()=>{boardMode=b.dataset.bm;renderBoard()});
}
async function renderFighters(){
  const el=$("#tab-board"), my=++boardTok;
  el.innerHTML='<div class="panel">'+boardTabs()+'<h2>Top Fighters</h2><div class="note" style="margin:0 0 10px">Win a battle to earn rank points (a boss win is worth more). Losing costs nothing.</div>'+
    '<button class="btn alt" id="bRef">Refresh</button><div id="bList" class="mute" style="margin-top:12px">Loading the scoreboard…</div></div>';
  $("#bRef").onclick=renderBoard;
  const list=$("#bList");
  if(!SAVE_URL){list.textContent="The scoreboard needs the save server to be turned on.";return}
  let players=null;
  const ctl=new AbortController(); const to=setTimeout(()=>ctl.abort(),12000);
  try{
    const r=await fetch(SAVE_URL+"?action=board&id="+encodeURIComponent(S.id),{signal:ctl.signal});
    const j=await r.json(); clearTimeout(to);
    if(j&&Array.isArray(j.players)) players=j.players;
  }catch(e){clearTimeout(to)}
  if(my!==boardTok)return;
  if(!players){list.innerHTML='<span style="color:var(--bad)">Could not load the scoreboard right now. Tap Refresh to try again.</span>';return}
  players=players.filter(p=>!p.you);
  players.push({name:S.name,rp:S.rp||0,w:S.w||0,l:S.l||0,you:true});
  const rows=players.map(p=>({name:String(p.name||"?"),rp:+p.rp||0,w:+p.w||0,l:+p.l||0,you:!!p.you}))
    .filter(r=>r.w+r.l>0).sort((a,b)=>b.rp-a.rp||b.w-a.w||a.l-b.l||a.name.localeCompare(b.name));
  if(!rows.length){list.textContent="No battles yet. Be the first!";return}
  let h="", rank=0;
  rows.forEach((r,i)=>{
    if(i===0||r.rp!==rows[i-1].rp)rank=i+1;
    h+='<div class="brow'+(r.you?' me':'')+'"><div class="bhead"><div class="rk'+(rank<=3?' g'+rank:'')+'">'+rank+'</div>'+
       '<div class="bn">'+esc(r.name)+(r.you?' (you)':'')+'</div>'+
       '<div class="bp"><b>'+r.rp+'</b> <span>pts · '+r.w+' W · '+r.l+' L</span></div></div></div>';
  });
  list.className=""; list.innerHTML=h;
}


function onBClick(e){
  if(!B||B.screen!=="arena"||B.busy)return;
  const t=e.target.closest(".bc"); if(!t)return;
  const side=t.dataset.s, i=+t.dataset.i;
  if(side==="me"&&canPick(i)){B.sel=i;B.mode=null;B.msg="Choose Attack or Upgrade for "+B.me[i].c[1]+".";renderBattle();return}
  if(side==="op"&&canTarget(side,i)){playerAttack(i)}
}
/* ================= WIRING ================= */
$("#tab-battle").addEventListener("click",onBClick);
$("#goBtn").onclick = login;
$("#idIn").addEventListener("keydown",e=>{if(e.key==="Enter")$("#nameIn").focus()});
$("#nameIn").addEventListener("keydown",e=>{if(e.key==="Enter")login()});
$("#outBtn").onclick = logout;
document.querySelectorAll("nav button").forEach(b=>b.onclick=()=>{sellArm=null;show(b.dataset.t)});
window.addEventListener("pagehide",()=>{if(S&&SAVE_URL)pushSave()});
window.__cg = {get S(){return S},get B(){return B},rollCard,PACKS,CARDS,SELL,get QUESTIONS(){return QUESTIONS},QUESTION_SETS,BATTLE,startBattle,beginBattle,mk};

